import { Link } from "gatsby"
import React, { useState } from 'react';
import { graphql } from 'gatsby';
import DonationModal, { DonationButton } from "../components/donation"

import Layout from '../components/layout';

const DownloadTemplate = ({ data }) => {
  const { markdownRemark } = data;
  const { html } = markdownRemark;
  const [showXMR, setShowXMR] = useState(false);
  
  return (
    <Layout>
        { showXMR && <DonationModal show={setShowXMR} /> }
        <ul className="breadcrumb">
        <li><Link to="/">Home</Link></li>
       <li>Download</li>
        </ul>
      <section style={{margin:0.5+`em`,overflow:`hidden`}}>
        <div dangerouslySetInnerHTML={{ __html: html }} />
      </section>
       <DonationButton show={setShowXMR} />
 <br/>
	  </Layout>
  );
};

export default DownloadTemplate;



export const pageQuery = graphql`
  query($slug: String!) {
  	markdownRemark(fields: { slug: { eq: $slug } }) {
      html
      frontmatter {
        date(formatString: "MMMM DD, YYYY")
        title
    }
  }
}`;
